import sys

def main():
    W, H, L, R, D, U = map(int, sys.stdin.read().split())
    M = 998244353
    N = W + H + 10
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % M
    inv = [1] * (N + 1)
    inv[N] = pow(fact[N], M - 2, M)
    for i in range(N, 0, -1):
        inv[i - 1] = inv[i] * i % M

    def C(n, k):
        if k < 0 or n < 0 or k > n:
            return 0
        return fact[n] * inv[k] % M * inv[n - k] % M

    def S(a, b):
        if a < 0 or b < 0:
            return 0
        return (C(a + b + 4, b + 2) - (b + 3) - (a + 1) * (b + 2)) % M

    def F(x, y):
        return (C(x + y + 2, x + 1) - 1) % M

    def K(x, y):
        return (C((W - x) + (H - y) + 2, (W - x) + 1) - 1) % M

    total = S(W, H)
    touch = (S(W - L, H - D) - S(W - R - 1, H - D)
             - S(W - L, H - U - 1) + S(W - R - 1, H - U - 1)) % M

    if L >= 1:
        for y in range(D, U + 1):
            touch += F(L - 1, y) * K(L, y)
    if D >= 1:
        for x in range(L, R + 1):
            touch += F(x, D - 1) * K(x, D)
    touch %= M

    print((total - touch) % M)

main()

import sys

def main():
    W, H, L, R, D, U = map(int, sys.stdin.read().split())
    M = 998244353
    N = W + H + 10
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % M
    inv = [1] * (N + 1)
    inv[N] = pow(fact[N], M - 2, M)
    for i in range(N, 0, -1):
        inv[i - 1] = inv[i] * i % M

    def C(n, k):
        if k < 0 or k > n or n < 0:
            return 0
        return fact[n] * inv[k] % M * inv[n - k] % M

    def Gs(n, m):
        # sum over x<n, y<m of G(x,y)
        b = C(n + m + 2, m + 1) - n - m - 2
        return (b - n * m) % M

    def G(x, y):
        if x < 0 or y < 0:
            return 0
        return (C(x + y + 2, x + 1) - 1) % M

    def Gp(x, y):
        return G(W - x, H - y)

    def rectG(a, b, c, d):
        if a > b or c > d:
            return 0
        return (Gs(b + 1, d + 1) - Gs(a, d + 1) - Gs(b + 1, c) + Gs(a, c)) % M

    def rectGp(a, b, c, d):
        if a > b or c > d:
            return 0
        return rectG(W - b, W - a, H - d, H - c)

    T1 = (rectG(0, W, 0, H) - rectG(L, W, D, H)) % M
    T2 = (rectGp(L, W, D, H) - rectGp(L, R, D, U)) % M
    T3 = 0
    if L >= 1:
        for y in range(U + 1, H + 1):
            T3 += G(L - 1, y) * Gp(L, y)
        T3 %= M
    T4 = 0
    if D >= 1:
        for x in range(R + 1, W + 1):
            T4 += G(x, D - 1) * Gp(x, D)
        T4 %= M
    print((T1 + T2 + T3 + T4) % M)

main()

import sys
def main():
    d=sys.stdin.read().split()
    n=int(d[0]); p=list(map(int,d[1:1+n]))
    # inversions via BIT, weighted by min position index heuristic
    ans=0
    tree=[0]*(n+1)
    def add(i):
        while i<=n:
            tree[i]+=1; i+=i&-i
    def q(i):
        s=0
        while i>0:
            s+=tree[i]; i-=i&-i
        return s
    for idx,v in enumerate(p):
        ans+=idx-q(v)
        add(v)
    print(ans)
main()

from typing import List

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            good = True
            for j in (i - k, i + k):
                if 0 <= j < n and nums[i] <= nums[j]:
                    good = False
                    break
            if good:
                total += nums[i]
        return total

reply:
The approach is to loop over each index and check its two neighbours at distance `k`. An index that is out of range is skipped. An element counts only if it is strictly greater than every neighbour that exists, and the good elements are summed.

Checking Example 1 by hand: the good elements are 3 (index 1), 5 (index 4) and 4 (index 5), giving 12. Example 2 gives 2.

