from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        D = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise order

        def need(w):
            return 0 if w == 2 else 2

        H0 = [[[0] * m for _ in range(n)] for _ in range(4)]
        H1 = [[[0] * m for _ in range(n)] for _ in range(4)]

        def order(di, dj):
            ro = range(n - 1, -1, -1) if di == 1 else range(n)
            co = range(m - 1, -1, -1) if dj == 1 else range(m)
            return ro, co

        # Straight-only states
        for k in range(4):
            di, dj = D[k]
            ro, co = order(di, dj)
            h = H0[k]
            for i in ro:
                row = grid[i]
                for j in co:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == need(row[j]):
                        h[i][j] = 1 + h[ni][nj]

        # States with one turn still available
        for k in range(4):
            di, dj = D[k]
            nk = (k + 1) % 4
            ti, tj = D[nk]
            ro, co = order(di, dj)
            h1 = H1[k]
            h1n = H1[k]
            h0t = H0[nk]
            for i in ro:
                row = grid[i]
                for j in co:
                    nw = need(row[j])
                    best = 0
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == nw:
                        best = 1 + h1n[ni][nj]
                    ti2, tj2 = i + ti, j + tj
                    if 0 <= ti2 < n and 0 <= tj2 < m and grid[ti2][tj2] == nw:
                        v = 1 + h0t[ti2][tj2]
                        if v > best:
                            best = v
                    h1[i][j] = best

        ans = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for k in range(4):
                        v = 1 + H1[k][i][j]
                        if v > ans:
                            ans = v
        return ans

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise order
        nxt = {1: 2, 2: 0, 0: 2}

        L = [[[0] * m for _ in range(n)] for _ in range(4)]
        F = [[[0] * m for _ in range(n)] for _ in range(4)]

        for k, (dr, dc) in enumerate(dirs):
            rs = list(range(n - 1, -1, -1)) if dr == 1 else list(range(n))
            cs = list(range(m - 1, -1, -1)) if dc == 1 else list(range(m))
            Lk = L[k]
            # L: forward chain, next cell processed first
            for i in rs:
                for j in cs:
                    x = grid[i][j]
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == nxt[x]:
                        Lk[i][j] = 1 + Lk[ni][nj]
                    else:
                        Lk[i][j] = 1
            # F: backward chain from start 1, predecessor processed first
            Fk = F[k]
            rr = rs[::-1]
            cc = cs[::-1]
            for i in rr:
                for j in cc:
                    x = grid[i][j]
                    if x == 1:
                        Fk[i][j] = 1
                        continue
                    pi, pj = i - dr, j - dc
                    if 0 <= pi < n and 0 <= pj < m and Fk[pi][pj] > 0 and nxt[grid[pi][pj]] == x:
                        Fk[i][j] = Fk[pi][pj] + 1
                    else:
                        Fk[i][j] = 0

        best = 0
        for i in range(n):
            for j in range(m):
                for k in range(4):
                    a = F[k][i][j]
                    if a == 0:
                        continue
                    best = max(best, a)
                    # turn clockwise
                    k2 = (k + 1) % 4
                    dr, dc = dirs[k2]
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == nxt[grid[i][j]]:
                        best = max(best, a + L[k2][ni][nj])
        return best

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        W = m + 2
        N = (n + 2) * W
        g = [-1] * N
        for i in range(n):
            s = (i + 1) * W + 1
            g[s:s + m] = grid[i]
        # value required right after the cell x
        e = [0 if v == 2 else 2 for v in g]
        cells = [(i + 1) * W + j + 1 for i in range(n) for j in range(m)]
        # directions in clockwise order: SE, SW, NW, NE
        D = [W + 1, W - 1, -W - 1, -W + 1]
        R0 = [[0] * N for _ in range(4)]
        R1 = [[0] * N for _ in range(4)]
        for k in range(4):
            off, r = D[k], R0[k]
            for x in (reversed(cells) if off > 0 else cells):
                y = x + off
                r[x] = r[y] + 1 if g[y] == e[x] else 1
        for k in range(4):
            off, r, r0 = D[k], R1[k], R0[(k + 1) % 4]
            for x in (reversed(cells) if off > 0 else cells):
                y = x + off
                if g[y] == e[x]:
                    a, b = r[y], r0[y]
                    r[x] = 1 + (a if a > b else b)
                else:
                    r[x] = 1
        ans = 0
        for x in cells:
            if g[x] == 1:
                ans = max(ans, max(R1[k][x] for k in range(4)))
        return ans

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # need[x][y]: value that must follow grid[x][y] in the sequence 1,2,0,2,0,...
        need = [[0 if v == 2 else 2 for v in row] for row in grid]
        # diagonal directions in clockwise order
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        def after(dx, dy):
            # G[x][y]: number of valid cells following (x, y) when moving in direction (dx, dy)
            G = [[0] * m for _ in range(n)]
            for x in (range(n - 1, -1, -1) if dx == 1 else range(n)):
                r = x + dx
                if not 0 <= r < n:
                    continue
                gr, Gr, nd = grid[r], G[r], need[x]
                if dy == 1:
                    G[x] = [g + 1 if t == e else 0 for g, t, e in zip(Gr[1:], gr[1:], nd[:-1])] + [0]
                else:
                    G[x] = [0] + [g + 1 if t == e else 0 for g, t, e in zip(Gr[:-1], gr[:-1], nd[1:])]
            return G

        def before(dx, dy):
            # B[x][y]: length of valid chain (starting at a 1) ending at (x, y) with last move (dx, dy)
            B = [[0] * m for _ in range(n)]
            for x in (range(n) if dx == 1 else range(n - 1, -1, -1)):
                row = grid[x]
                r = x - dx
                if 0 <= r < n:
                    pb, pn = B[r], need[r]
                    if dy == 1:
                        core = [0] + [p + 1 if p and e == t else 0 for p, e, t in zip(pb[:-1], pn[:-1], row[1:])]
                    else:
                        core = [p + 1 if p and e == t else 0 for p, e, t in zip(pb[1:], pn[1:], row[:-1])] + [0]
                else:
                    core = [0] * m
                B[x] = [1 if v == 1 else k for v, k in zip(row, core)]
            return B

        Gs = [after(dx, dy) for dx, dy in dirs]
        best = 0
        for i, (dx, dy) in enumerate(dirs):
            B = before(dx, dy)
            G1, G2 = Gs[i], Gs[(i + 1) % 4]
            for x in range(n):
                cand = max((b + (g1 if g1 > g2 else g2) for b, g1, g2 in zip(B[x], G1[x], G2[x]) if b), default=0)
                if cand > best:
                    best = cand
        return best

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        D = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        nxt = {1: 2, 2: 0, 0: 2}

        def order_rows(di):
            return range(n - 1, -1, -1) if di == 1 else range(n)

        # Straight-run lengths for each direction
        A = []
        for d in range(4):
            di, dj = D[d]
            arr = [[0] * m for _ in range(n)]
            for i in order_rows(di):
                for j in range(m):
                    ni, nj = i + di, j + dj
                    val = 1
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == nxt[grid[i][j]]:
                        val += arr[ni][nj]
                    arr[i][j] = val
            A.append(arr)

        best = 0
        # Runs allowing one clockwise turn
        for d in range(4):
            di, dj = D[d]
            cd = (d + 1) % 4
            ci, cj = D[cd]
            Ac = A[cd]
            F = [[0] * m for _ in range(n)]
            for i in order_rows(di):
                for j in range(m):
                    want = nxt[grid[i][j]]
                    best_next = 0
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == want:
                        best_next = max(best_next, F[ni][nj])
                    ti, tj = i + ci, j + cj
                    if 0 <= ti < n and 0 <= tj < m and grid[ti][tj] == want:
                        best_next = max(best_next, Ac[ti][tj])
                    F[i][j] = 1 + best_next
                    if grid[i][j] == 1 and F[i][j] > best:
                        best = F[i][j]
        return best

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # clockwise order: SE, SW, NW, NE
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        H = [[[0] * m for _ in range(n)] for _ in range(4)]
        F = [[[0] * m for _ in range(n)] for _ in range(4)]

        # H: longest chain starting at a 1 ending at (i,j) moving in direction k
        for k, (dr, dc) in enumerate(dirs):
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            Hk = H[k]
            for i in rows:
                pi = i - dr
                for j in range(m):
                    v = grid[i][j]
                    if v == 1:
                        Hk[i][j] = 1
                    elif v == 0 or v == 2:
                        pj = j - dc
                        if 0 <= pi < n and 0 <= pj < m:
                            p = grid[pi][pj]
                            hp = Hk[pi][pj]
                            if hp > 0 and ((v == 2 and p != 2) or (v == 0 and p == 2)):
                                Hk[i][j] = hp + 1

        # F: longest alternating chain starting at (i,j) moving in direction k
        for k, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            Fk = F[k]
            for i in rows:
                ni = i + dr
                for j in range(m):
                    v = grid[i][j]
                    if v == 0 or v == 2:
                        f = 1
                        nj = j + dc
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2 - v:
                            f += Fk[ni][nj]
                        Fk[i][j] = f

        ans = 0
        for k in range(4):
            for i in range(n):
                for j in range(m):
                    if H[k][i][j] > ans:
                        ans = H[k][i][j]

        for i in range(n):
            for j in range(m):
                v = grid[i][j]
                if v != 0 and v != 2:
                    continue
                for k in range(4):
                    h = H[k][i][j]
                    if h == 0:
                        continue
                    d2 = (k + 1) % 4
                    ni = i + dirs[d2][0]
                    nj = j + dirs[d2][1]
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2 - v:
                        cand = h + F[d2][ni][nj]
                        if cand > ans:
                            ans = cand
        return ans

reply:
## Approach

A V-segment is two diagonal arms sharing a corner cell. The values after the leading 1 alternate 2, 0, 2, 0, …, so each arm is a chain where consecutive values alternate.

1. **Arm ending at a cell (`H[k][i][j]`):** the longest valid chain starting at a 1 and ending at `(i, j)`, moving in direction `k`. A cell with value 1 starts a chain (length 1). A cell with value 2 extends a chain whose previous value is 0 or 1. A cell with value 0 extends a chain whose previous value is 2. Rows are processed in an order that guarantees the predecessor is computed first.

2. **Arm starting after a cell (`F[k][i][j]`):** the longest alternating chain starting at `(i, j)` and moving in direction `k`. It is computed in the reverse order, so the successor is ready first.

3. **Combining:** for each cell `c` with value 0 or 2, and each arm direction `d1` with `H[d1][c] > 0`, the clockwise direction `d2` is the next entry in the cyclic list `SE → SW → NW → NE`. The second arm starts at the neighbour `c + d2`, which must hold the opposite value (`2 - grid[c]`). The candidate length is `H[d1][c] + F[d2][c+d2]`.

4. The answer is the maximum over all straight chains (`H` values) and all turn candidates. A turn at the leading 1 is already covered by a straight chain, so it needs no separate case.

The running time is O(4·n·m), about 1M cell visits for a 500×500 grid.

I checked the logic by hand against Example 3 (the straight diagonal 1,2,0,2,0 gives 5) and Example 4 (`[[1]]` gives 1). I did not run the code.

