from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        N = n + 2
        M = m + 2
        g = [[-1] * M for _ in range(N)]
        for i in range(n):
            for j in range(m):
                g[i + 1][j + 1] = grid[i][j]
        D = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise order
        f0 = [[[0] * M for _ in range(N)] for _ in range(4)]
        f1 = [[[0] * M for _ in range(N)] for _ in range(4)]

        def rows_for(di):
            return range(n, 0, -1) if di == 1 else range(1, n + 1)

        # f0: straight only
        for k in range(4):
            di, dj = D[k]
            F = f0[k]
            for i in rows_for(di):
                gi = g[i]
                Fi = F[i]
                gn = g[i + di]
                Fn = F[i + di]
                for j in range(1, m + 1):
                    v = gi[j]
                    e = 0 if v == 2 else 2
                    nj = j + dj
                    Fi[j] = 1 + (Fn[nj] if gn[nj] == e else 0)

        # f1: one clockwise turn still allowed
        for k in range(4):
            di, dj = D[k]
            nd = (k + 1) % 4
            ddi, ddj = D[nd]
            F = f1[k]
            Fs = f1[k]
            Ft = f0[nd]
            for i in rows_for(di):
                gi = g[i]
                Fi = F[i]
                gn = g[i + di]
                Fn = Fs[i + di]
                gt = g[i + ddi]
                Ftr = Ft[i + ddi]
                for j in range(1, m + 1):
                    v = gi[j]
                    e = 0 if v == 2 else 2
                    best = 0
                    nj = j + dj
                    if gn[nj] == e:
                        best = Fn[nj]
                    tj = j + ddj
                    if gt[tj] == e:
                        t = Ftr[tj]
                        if t > best:
                            best = t
                    Fi[j] = 1 + best

        ans = 0
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if g[i][j] == 1:
                    for k in range(4):
                        if f1[k][i][j] > ans:
                            ans = f1[k][i][j]
        return ans

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        D = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise order
        F = []
        G = []
        for dr, dc in D:
            Fk = [[0] * m for _ in range(n)]
            Gk = [[0] * m for _ in range(n)]
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            for i in rows:
                for j in range(m):
                    v = grid[i][j]
                    if v == 1:
                        Fk[i][j] = 1
                    else:
                        pi = i - dr
                        pj = j - dc
                        if 0 <= pi < n and 0 <= pj < m:
                            p = Fk[pi][pj]
                            if p and v == (2 if p & 1 else 0):
                                Fk[i][j] = p + 1
            rows2 = range(n - 1, -1, -1) if dr == 1 else range(n)
            for i in rows2:
                for j in range(m):
                    v = grid[i][j]
                    if v != 1:
                        g = 1
                        ni = i + dr
                        nj = j + dc
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2 - v:
                            g = 1 + Gk[ni][nj]
                        Gk[i][j] = g
            F.append(Fk)
            G.append(Gk)

        ans = 0
        for k in range(4):
            k2 = (k + 1) % 4
            Fk = F[k]
            Gn = G[k2]
            for i in range(n):
                for j in range(m):
                    f = Fk[i][j]
                    if f:
                        if f > ans:
                            ans = f
                        c = f + Gn[i][j] - 1
                        if c > ans:
                            ans = c
        return ans

from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        diags = {}
        for i in range(n):
            for j in range(n):
                diags.setdefault(i - j, []).append(grid[i][j])
        for d, vals in diags.items():
            if d >= 0:
                vals.sort(reverse=True)
            else:
                vals.sort()
        pos = {d: 0 for d in diags}
        for i in range(n):
            for j in range(n):
                d = i - j
                grid[i][j] = diags[d][pos[d]]
                pos[d] += 1
        return grid

