class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        starts = [(i, 0) for i in range(n)] + [(0, j) for j in range(1, n)]
        for si, sj in starts:
            cells = []
            i, j = si, sj
            while i < n and j < n:
                cells.append((i, j))
                i += 1
                j += 1
            vals = [grid[i][j] for i, j in cells]
            if si >= sj:
                vals.sort(reverse=True)
            else:
                vals.sort()
            for (i, j), v in zip(cells, vals):
                grid[i][j] = v
        return grid

