    def permute(self, n: int, k: int) -> List[int]:
        def cnt(o, e, L):
            # o: remaining odds, e: remaining evens, L: parity of last placed (None if none)
            length = o + e
            if length == 0:
                return 1
            total = 0
            # q = 0 means next pattern starts with odd, q = 1 means starts with even
            for q in (0, 1):
                if L is not None and q == L:
                    continue
                if q == 0:
                    if o == (length + 1) // 2 and e == length // 2:
                        total += factorial(o) * factorial(e)
                else:
                    if e == (length + 1) // 2 and o == length // 2:
                        total += factorial(o) * factorial(e)
            return total

        odds = (n + 1) // 2
        evens = n // 2
        if k > cnt(odds, evens, None):
            return []

        remaining = list(range(1, n + 1))
        res = []
        last = None
        for _ in range(n):
            picked = False
            for v in remaining:
                p = v % 2
                if last is not None and p == last:
                    continue
                o = sum(1 for x in remaining if x % 2 == 1)
                e = len(remaining) - o
                if p == 1:
                    o -= 1
                else:
                    e -= 1
                c = cnt(o, e, p)
                if k <= c:
                    res.append(v)
                    remaining.remove(v)
                    last = p
                    picked = True
                    break
                k -= c
            if not picked:
                return []
        return res

