    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = fact[i - 1] * i

        def count(o: int, e: int, p: int) -> int:
            # o odd / e even values remain; next element must have parity p (1 = odd, 0 = even)
            m = o + e
            if m == 0:
                return 1
            if p == 1:
                if o == (m + 1) // 2 and e == m // 2:
                    return fact[o] * fact[e]
            else:
                if e == (m + 1) // 2 and o == m // 2:
                    return fact[o] * fact[e]
            return 0

        remaining = list(range(1, n + 1))
        res = []
        last = -1
        o = (n + 1) // 2
        e = n // 2
        for _ in range(n):
