from typing import List


class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = fact[i - 1] * i

        def g(o, e, last):
            # number of alternating completions with o odds, e evens remaining,
            # last placed parity 'last' (None if nothing placed yet)
            L = o + e
            if L == 0:
                return 1
            odd_start_ok = (o == (L + 1) // 2 and e == L // 2)
            even_start_ok = (e == (L + 1) // 2 and o == L // 2)
            if last is None:
                cnt = int(odd_start_ok) + int(even_start_ok)
            elif last == 1:
                cnt = int(even_start_ok)
            else:
                cnt = int(odd_start_ok)
            return cnt * fact[o] * fact[e]

        o0 = (n + 1) // 2
        e0 = n // 2
        total = g(o0, e0, None)
        if k > total:
            return []

        res = []
        used = [False] * (n + 1)
        o, e = o0, e0
        for _ in range(n):
            for v in range(1, n + 1):
                if used[v]:
                    continue
                p = v % 2
                if res and p == res[-1] % 2:
                    continue
                no = o - (1 if p == 1 else 0)
                ne = e - (1 if p == 0 else 0)
                c = g(no, ne, p)
                if k <= c:
                    used[v] = True
                    o, e = no, ne
                    res.append(v)
                    break
                k -= c
        return res

class Solution:
